// Derived from floorplan v0.11.0 (MIT): skills/floorplan/assets/query-cli.mjs
// modelmap/query.mjs: look things up in this folder's graph.json. Generated by build.mjs; the Claude
// Code CLI calls it when you ask questions from the map (node modelmap/serve.mjs).
//
// usage: node modelmap/query.mjs overview
//        node modelmap/query.mjs find "<words>" [--kind block|attention|mlp|norm|embed|linear|other|external] [--limit 15]
//        node modelmap/query.mjs show <id>
//        node modelmap/query.mjs params <id> [--top 10]
//        node modelmap/query.mjs contract
//        node modelmap/query.mjs path <fromId> <toId>
// Ids look like n:root, n:blocks, n:blocks.0.attn. Every output is JSON; an error is {"error": "..."} with exit code 1.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const COMMANDS = ['overview', 'find "<words>" [--kind <kind>] [--limit 15]', 'show <id>', 'params <id> [--top 10]', 'contract', 'path <fromId> <toId>'];
const argv = process.argv.slice(2);
const flag = (name) => { const i = argv.indexOf('--' + name); if (i < 0) return undefined; const v = argv[i + 1]; argv.splice(i, 2); return v; };
const kind = flag('kind'), limit = flag('limit'), top = flag('top');
const [cmd, ...rest] = argv;
const needId = (n) => { if (rest.length < n || rest.slice(0, n).some((x) => !String(x).trim())) throw new Error(cmd + ' needs ' + (n === 1 ? 'an id' : n + ' ids') + ', like n:blocks'); };
try {
  const G = JSON.parse(fs.readFileSync(path.join(here, 'graph.json'), 'utf8').replace(/^﻿/, ''));
  const q = createGraphQuery(G);
  let out;
  if (!cmd) out = { commands: COMMANDS };
  else if (cmd === 'overview') out = q.overview();
  else if (cmd === 'find') out = q.find(rest.join(' '), kind, limit);
  else if (cmd === 'show') { needId(1); out = q.show(rest[0]); }
  else if (cmd === 'params') { needId(1); out = q.params(rest[0], top); }
  else if (cmd === 'contract') out = q.contract();
  else if (cmd === 'path') { needId(2); out = q.path(rest[0], rest[1]); }
  else throw new Error('unknown command "' + cmd + '"; commands: ' + COMMANDS.join(' | '));
  console.log(JSON.stringify(out, null, 1));
} catch (e) {
  console.log(JSON.stringify({ error: e.message }));
  process.exit(1);
}
